import type { VerticalTabBarPanelProps } from "../vertical-tab-bar.types";

import { forwardRef } from "react";
import * as RadixTabs from "@radix-ui/react-tabs";
import { clsx } from "clsx";

import { VerticalTabBarClasses } from "../vertical-tab-bar.styles";

export const VerticalTabBarPanel = forwardRef<
  HTMLDivElement,
  VerticalTabBarPanelProps & RadixTabs.TabsContentProps
>(({ className, children, value, ...props }, ref) => {
  return (
    <RadixTabs.Content
      ref={ref}
      className={clsx(VerticalTabBarClasses.panel, className)}
      value={value}
      {...props}
    >
      {children}
    </RadixTabs.Content>
  );
});

VerticalTabBarPanel.displayName = "VerticalTabBar.Panel";
